const finalOutput = {
  response: $('Data from Backend').first().json.body.response,
  query: $('Data from Backend').first().json.body.query
};

items.forEach(item => {
  const key = item.json.field;
  const value = item.json.output;

  if (key) {
    finalOutput[key] = value;
  }
});

return { json: finalOutput };

const weights = {
  correctness_topical: 0.42,
  coherence_logical: 0.28,
  coherence_stylistic: 0.32,
  coverage_broad: 0.37,
  coverage_deep: 0.39,
  consistency_internal: 0.39
};

const totalWeight = weights.correctness_topical + weights.coherence_logical + weights.coherence_stylistic + weights.coverage_broad + weights.coverage_deep + weights.consistency_internal;

for (const item of items) {
  const json = item.json;

  const weightedSum = 
    ($input.first().json.correctness_topical.grade * weights.correctness_topical) +
    ($input.first().json.coherence_logical.grade * weights.coherence_logical) +
    ($input.first().json.coherence_stylistic.grade * weights.coherence_stylistic) +
    ($input.first().json.coverage_broad.grade * weights.coverage_broad) +
    ($input.first().json.coverage_deep.grade * weights.coverage_deep) +
    ($input.first().json.consistency_internal.grade * weights.consistency_internal);

  const overallGrade = weightedSum / totalWeight;

  item.json.quality_overall = {
    grade: Number(overallGrade.toFixed(1))
  };
}

return items;

